//

import WidgetKit
import SwiftUI

struct Provider: TimelineProvider {
    func placeholder(in context: Context) -> SimpleEntry {
        SimpleEntry(date: Date(), lunar: ("二零二六", "正月", "十五"), shiChen: "午时 (11:00-13:00)", solarTerm: "立春")
    }

    func getSnapshot(in context: Context, completion: @escaping (SimpleEntry) -> Void) {
        let entry = SimpleEntry(date: Date(), lunar: ("二零二六", "正月", "十五"), shiChen: "午时 (11:00-13:00)", solarTerm: "立春")
        completion(entry)
    }

    func getTimeline(in context: Context, completion: @escaping (Timeline<Entry>) -> Void) {
        let currentDate = Date()

        // 调用纯本地算法
        let lunar = LunarCalendar.convertToLunar(date: currentDate)
        let shiChen = LunarCalendar.getShiChen(date: currentDate)
        let solarTerm = LunarCalendar.getSolarTerm(date: currentDate)

        let entry = SimpleEntry(date: currentDate, lunar: lunar, shiChen: shiChen, solarTerm: solarTerm)

        // 每分钟刷新一次 (policy: .atEndOfMinute)
        let timeline = Timeline(entries: [entry], policy: .atEndOfMinute)
        completion(timeline)
    }
}

struct SimpleEntry: TimelineEntry {
    let date: Date
    let lunar: (year: String, month: String, day: String, isLeap: Bool)
    let shiChen: String
    let solarTerm: String
}
