# 八卦权重矩阵：个体 | 群体 | 全球（行和恒等于1）
HEXAGRAM_MATRIX: Dict[八卦, Dict[str, float]] = {
    八卦.乾卦: {"ind": 0.6, "grp": 0.3, "glb": 0.1},
