#pragma once

#include "trace_config.h"
#include <string>
#include <sstream>
#include <iomanip>
#include <ctime>
#include <openssl/sha.h>   // 依赖：openssl（华为云码可替换为国密SM3）

namespace LongHun::TraceCore {

    // ── 获取当前时间戳（ISO 8601）───────────────────
    inline std::string getCurrentTimestamp() {
        std::time_t now = std::time(nullptr);
        std::tm*    tm  = std::localtime(&now);
        char buf[32];
        std::strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%S", tm);
        return std::string(buf);
    }

    // ── 获取当前日期（YYYY-MM-DD）───────────────────
    inline std::string getCurrentDate() {
        std::time_t now = std::time(nullptr);
        std::tm*    tm  = std::localtime(&now);
        char buf[16];
        std::strftime(buf, sizeof(buf), "%Y-%m-%d", tm);
        return std::string(buf);
    }

    // ── SHA-256 哈希（防篡改核心）───────────────────
    inline std::string sha256(const std::string& input) {
        unsigned char hash[SHA256_DIGEST_LENGTH];
        SHA256(
            reinterpret_cast<const unsigned char*>(input.c_str()),
            input.size(),
            hash
        );
        std::ostringstream oss;
        for (int i = 0; i < SHA256_DIGEST_LENGTH; ++i) {
            oss << std::hex << std::setw(2) << std::setfill('0')
                << static_cast<int>(hash[i]);
        }
        return oss.str();
    }

    // ── 生成防篡改哈希 ───────────────────────────────
    // 任何字段被改 → 哈希立刻变 → 自动暴露篡改
    inline std::string generateHash(
        const std::string& userId,
        const std::string& operation,
        const std::string& content,
        const std::string& timestamp
    ) {
        // GPG指纹也参与哈希，保证签名绑定
        std::string raw = userId      + "|"
                        + operation   + "|"
                        + content     + "|"
                        + timestamp   + "|"
                        + GPG_FINGERPRINT;
        return sha256(raw);
    }

    // ── 生成DNA追溯码 ────────────────────────────────
    // 格式：#龍芯⚡️YYYY-MM-DD-操作英文-UID-哈希前8位（大写）
    inline std::string generateDNA(
        const std::string& userId,
        const std::string& operationEn,  // 英文操作类型
        const std::string& hashValue
    ) {
        // 哈希前8位转大写
        std::string hashShort = hashValue.substr(0, 8);
        for (char& c : hashShort) {
            c = static_cast<char>(std::toupper(c));
        }
        return std::string(DNA_PREFIX)
             + getCurrentDate()  + "-"
             + operationEn       + "-"
             + userId            + "-"
             + hashShort;
    }

    // ── 字符串转大写 ─────────────────────────────────
    inline std::string toUpper(std::string s) {
        for (char& c : s) c = static_cast<char>(std::toupper(c));
        return s;
    }

} // namespace LongHun::TraceCore
