```python
from fastapi import FastAPI, HTTPException
from pydantic import BaseModel
from typing import List, Dict
import dashscope  # 通义千问SDK
import json
import os

# 配置API Key (请替换为你的真实Key)
dashscope.api_key = "YOUR_QIANWEN_API_KEY"

app = FastAPI(title="龙芯企业灯 v2.0")

# --- 数据模型 ---
class SymptomInput(BaseModel):
    symptoms: List[str]
    problem_description: str

class PressureInput(BaseModel):
    finance: int; team: int; market: int; decision: int; personal: int

class MetricsInput(BaseModel):
    revenue: float; cash_flow_months: int; retention_rate: float

class DiagnosisRequest(BaseModel):
    symptoms: SymptomInput
    pressure: PressureInput
    metrics: MetricsInput

# --- AI 引擎封装 ---
def call_qianwen(prompt: str) -> dict:
    try:
        response = dashscope.Generation.call(
            model='qwen-max',
            messages=[{'role': 'user', 'content': prompt}],
            result_format='message'
        )
        if response.status_code == 200:
            content = response.output.choices[0].message.content
            # 清理Markdown标记
            content = content.replace('```json', '').replace('```', '').strip()
            return json.loads(content)
        else:
            raise Exception(f"AI Error: {response.code}")
    except Exception as e:
        return {"error": str(e)}

# --- 核心业务逻辑 ---

@app.post("/api/diagnose")
async def run_diagnosis(req: DiagnosisRequest):
    """
    三才算法核心入口：
    1. 前生灯 (因果分析)
    2. 今世灯 (压力测算)
    3. 未来灯 (路径规划)
    """

    # 1. 前生灯：照见根因
    mirror_prompt = f"""
    [角色] 资深企业诊断专家 (曾仕强易经智慧应用者)
    [任务] 分析企业病根
    [症状] {', '.join(req.symptoms.symptoms)}
    [描述] {req.symptoms.problem_description}
    [要求] 输出JSON: {{ "root_cause": "一句话根因", "timeline": [{{"year": -3, "event": "..."}}, ...], "checklist": ["是否...", "..."] }}
    """
    mirror_result = call_qianwen(mirror_prompt)

    # 2. 今世灯：称量现状
    total_pressure = sum(vars(req.pressure).values())
    status = "高危" if total_pressure > 40 else "警戒" if total_pressure > 30 else "安全"

    scale_result = {
        "pressure_score": total_pressure,
        "status": status,
        "decision_point": "跪着求存" if total_pressure > 40 and req.metrics.cash_flow_months < 3 else "站着改革"
    }

    # 3. 未来灯：照亮活路
    light_prompt = f"""
    [角色] 战略顾问
    [现状] 压力{total_pressure}分, 抉择点:{scale_result['decision_point']}, 现金流:{req.metrics.cash_flow_months}个月
    [要求] 给出3条具体路径 (JSON格式): [{{"name": "...", "actions": ["...", "..."], "risk": "...", "success_rate": 0.x}}]
    """
    light_result = call_qianwen(light_prompt)

    # 生成DNA追溯码
    import datetime
    dna_code = f"#龍芯⚡️{datetime.date.today()}-DIAG-{os.urandom(4).hex()}"

    return {
        "dna_trace": dna_code,
        "mirror": mirror_result,
        "scale": scale_result,
        "light": light_result,
        "master_note": "理论指导：曾仕强老师 | 核心算法：三才变量 v2.0"
    }

if __name__ == "__main__":
    import uvicorn
    print("🚀 龙芯企业灯 v2.0 启动中... DNA系统已就绪")
    uvicorn.run(app, host="0.0.0.0", port=8000)
```

